OutputArray elements are: 1 2 3 4 5 2. Dynamic Sized Arrays:The size of a dynamic array can change during program execution.Elements can be added or removed as needed.Memory is allocated and de-allocated automatically.Don’t need to worry about the array size in advance.Dynamic arrays are flexible and useful when the number of elements is unknown.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int main()
{
     // dynamic array
    vector<int> arr;

    // adding elements
    arr.push_back(10);
    arr.push_back(20);
    arr.push_back(30);

    // printing array elements
    cout << "Array elements are: ";
    for (int i = 0; i < arr.size(); i++)
    {
        cout << arr[i] << " ";
    }

    // removing last element
    arr.pop_back();

    cout << "\nAfter removing last element: ";
    for (int i = 0; i < arr.size(); i++)
    {
        cout << arr[i] << " ";
    }

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

int main()
{
    // pointer for dynamic array
    int *arr = NULL; 
    int size = 0;

    // adding elements dynamically
    size++;
    arr = (int *)realloc(arr, size * sizeof(int));
    arr[size - 1] = 10;

    size++;
    arr = (int *)realloc(arr, size * sizeof(int));
    arr[size - 1] = 20;

    size++;
    arr = (int *)realloc(arr, size * sizeof(int));
    arr[size - 1] = 30;

    // printing array elements
    printf("Array elements are: ");
    for (int i = 0; i < size; i++)
    {
        printf("%d ", arr[i]);
    }

    // removing last element
    size--; 
    printf("\nAfter removing last element: ");
    for (int i = 0; i < size; i++)
    {
        printf("%d ", arr[i]);
    }

    free(arr); // free memory
    return 0;
}


            Java

    import java.util.ArrayList;

public class Main {
    public static void main(String[] args)
    {
        // dynamic array
        ArrayList<Integer> arr = new ArrayList<>();

        // adding elements
        arr.add(10);
        arr.add(20);
        arr.add(30);

        // printing array elements
        System.out.print("Array elements are: ");
        for (int num : arr) {
            System.out.print(num + " ");
        }

        // removing last element
        arr.remove(arr.size() - 1);

        System.out.print("\nAfter removing last element: ");
        for (int num : arr) {
            System.out.print(num + " ");
        }
    }
}


